changeSet.sql:
UPDATE company_config_property
SET description = 'Number of days before the platform should automatically create a disconnect order from completing Move, Add, and Change orders.'
WHERE company_config_property_id IN (22, 23);

UPDATE company_config_property
SET description = 'Level of Effort default value.'
WHERE company_config_property_id IN (31);

 UPDATE company_config_property
 SET description = 'Level of Effort default value.'
     WHERE config_property_key = 'LOE_DEFAULT';

 UPDATE company_config_property
 SET description = 'Number of days before the platform should automatically create a disconnect order from completing Move, Add, and Change orders.'
 WHERE config_property_key = 'DISCONNECT_DELAY';

 UPDATE company_config_property
 SET modifiable = 1
 WHERE config_property_key IN (
     'DISCONNECT_DELAY', 'NEW_QUOTE_URL', 'CLIENT_ID_UNIQUE_CONSTRAINT', 'LOCK_ONE_LOCATION_PER_ORDER', 'LOE_DEFAULT');


 UPDATE company_config_property
 SET type = 'boolean'
 WHERE config_property_key IN (
 'CLIENT_ID_UNIQUE_CONSTRAINT', 'LOCK_ONE_LOCATION_PER_ORDER' );

 UPDATE company_config_property
 SET description = 'Time interval before the system automatically disconnects.'
 WHERE config_property_key ='DISCONNECT_DELAY';

 UPDATE company_config_property
 SET description = 'Flag indicating unique client IDs.'
 WHERE config_property_key ='CLIENT_ID_UNIQUE_CONSTRAINT';

UPDATE company_config_property
 SET description = 'Flag indicating whether the system restricts orders to have only one associated location.'
 WHERE config_property_key ='LOCK_ONE_LOCATION_PER_ORDER';

UPDATE company_config_property
SET description = '# of days before the platform should automatically create a disconnect order from completing Move, Add, and Change orders'
WHERE config_property_key = 'DISCONNECT_DELAY';
UPDATE company_config_property
SET description = 'URL link associated to the "New Quote" module on the landing page'
WHERE config_property_key = 'NEW_QUOTE_URL';
